import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class ConcurrencyCollectionsDemo {

    public static void main(String[] args) throws InterruptedException {
        // 1. Synchronized wrapper iteration protocol
        List<String> syncList = Collections.synchronizedList(new ArrayList<>());
        syncList.add("ALPHA");
        syncList.add("BETA");
        syncList.add("GAMMA");

        // Correct iteration: explicit synchronization on the wrapper monitor
        synchronized (syncList) {
            for (String item : syncList) {
                System.out.println("Synchronized iteration item: " + item);
            }
        }

        // 2. High-performance ConcurrentHashMap with atomic compute
        ConcurrentHashMap<String, Integer> pageVisits = new ConcurrentHashMap<>();
        pageVisits.put("/home", 100);

        // Atomic atomic update without external locking
        pageVisits.compute("/home", (k, v) -> v == null ? 1 : v + 1);
        pageVisits.computeIfAbsent("/pricing", k -> 1);

        System.out.println("Page visits: " + pageVisits);

        // 3. CopyOnWriteArrayList snapshot iteration
        CopyOnWriteArrayList<String> listeners = new CopyOnWriteArrayList<>();
        listeners.add("AuthListener");
        listeners.add("AuditListener");

        // Iteration captures array snapshot; in-flight mutation does not throw CME
        System.out.println("Starting CopyOnWrite traversal...");
        for (String listener : listeners) {
            System.out.println("Notifying: " + listener);
            // Safe in-flight mutation during iteration
            if (listener.equals("AuthListener")) {
                listeners.add("MetricsListener");
            }
        }

        System.out.println("Listeners after iteration mutation: " + listeners);
    }
}
```

