import java.util.concurrent.ConcurrentHashMap;

public class MetricAggregator {
    private final ConcurrentHashMap<String, Long> metrics = new ConcurrentHashMap<>();

    public void recordEvent(String metricName) {
        if (metricName != null) {
            metrics.merge(metricName, 1L, Long::sum);
        }
    }

    public long getCount(String metricName) {
        if (metricName == null) return 0;
        return metrics.getOrDefault(metricName, 0L);
    }
}

